import { formatSlot } from './format-slot.js';

/** What a slot chip says: slotChip({ start: '14:00', end: '15:00', left: 3 }) → '14:00–15:00 · 3 left'. */
export const slotChip = ({ start, end, left }) => `${formatSlot(start, end)} · ${left > 0 ? `${left} left` : 'full'}`;

const count = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;

/** What a screen reader says for the basket's hold timer: holdTimerLabel(899) → 'Slot held for 14 minutes 59 seconds'. */
export const holdTimerLabel = (seconds) => `Slot held for ${count(Math.floor(seconds / 60), 'minute')} ${count(seconds % 60, 'second')}`;

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { slotChip } from '../slot-chip.js';
import { holdTimerLabel } from '../hold-timer.js';

test('slotChip says the slot and how many are left', () => {
  assert.equal(slotChip({ start: '14:00', end: '15:00', left: 3 }), '14:00–15:00 · 3 left');
  assert.equal(slotChip({ start: '14:00', end: '15:00', left: 0 }), '14:00–15:00 · full');
});

test('holdTimerLabel reads the time left in words', () => {
  assert.equal(holdTimerLabel(899), 'Slot held for 14 minutes 59 seconds');
  assert.equal(holdTimerLabel(61), 'Slot held for 1 minute 1 second');
});

